/**
 * Declares the HTML component import type and the Vitemple store API available to TypeScript projects.
 * These declarations describe compiler-provided globals and do not implement runtime behavior.
 */
declare module "*.html?temple" {

  /** Mounts an imported HTML component into a DOM node and returns its lifecycle handle. */
  const mount: (
    target: Node,
    params?: Record<string, unknown>,
  ) => {
    nodes: Node[];

    /** Runs registered cleanup and removes all nodes owned by this component instance. */
    destroy(): void;
  };

  export default mount;
}

/** Describes the single page-wide reactive store generated by Vitemple. */
interface TempleStore<T extends object = Record<string, unknown>> {

  /** Returns the current shared state object. */
  value: T;

  /** Replaces the current state and notifies subscribers. */
  set(next: T): void;

  /** Adds only keys missing from the current or session-restored state. */
  init(initial: Partial<T>): void;

  /** Computes and stores the next state from the current state. */
  update(updater: (current: T) => T): void;

  /** Registers a listener, invokes it immediately, and returns its unsubscribe function. */
  subscribe(listener: (value: T) => void): () => void;
}

/** The reactive store provided by the Vitemple runtime in compiled page scripts. */
declare const store: TempleStore<any>;
